def all_edges(graph):
    for edges in graph["edges_by_source"].values():
        yield from edges


def _resolve_symbols(graph, name):
    """Exact name match first; only fall back to the regex/substring search
    `find_symbols` does if nothing matches exactly. Ambiguous callers get the
    exact-match set, not a flood of unrelated substring hits."""
    exact = graph["by_name"].get(name)
    if exact:
        return exact
    return find_symbols(graph, name) if name else []


# ---------------------------------------------------------------------------
# Step 4: assertion evaluators
# ---------------------------------------------------------------------------

CALL_RELATION_TYPES = {"CALLS", "ASYNC_CALLS"}

# Heuristic for "looks like a test file": a `test`/`tests`/`__tests__` path
# segment, or a filename ending in `_test.<ext>` — stated here because
# test_references has no other definition of "test" to go on.
TEST_PATH_PATTERN = re.compile(r"(^|/)(tests?|__tests__)(/|$)|_test\.[^/.]+$", re.IGNORECASE)


def eval_symbol_exists(args, graph):
    """Regex SEARCH (substring-position match, not full-string equality)
    against symbol name and qualified_name. A pattern of "run" matches
    "run_entire". Never None - the graph can always answer existence."""
    return bool(find_symbols(graph, args.get("pattern", "")))


def eval_has_inbound_edge(args, graph):
    """Any relation at all - of any type, from any source - whose to_id
    lands on this symbol. False (not None) when the symbol itself doesn't
    exist: a nonexistent symbol definitively has no inbound edge."""
    ids = {s["id"] for s in _resolve_symbols(graph, args.get("symbol", ""))}
    if not ids:
        return False
    return any(edge.get("to_id") in ids for edge in all_edges(graph))


def eval_calls(args, graph):
    """A CALLS/ASYNC_CALLS relation from a caller-matching id to a
    callee-matching id. The snapshot's relation_set does distinguish call
    edges from other relation types, so this is a real check, not a guess."""
    caller_ids = [s["id"] for s in _resolve_symbols(graph, args.get("caller", ""))]
    callee_ids = {s["id"] for s in _resolve_symbols(graph, args.get("callee", ""))}
    if not caller_ids or not callee_ids:
        return False
    for cid in caller_ids:
        for edge in graph["edges_by_source"].get(cid, []):
            if edge.get("type") in CALL_RELATION_TYPES and edge.get("to_id") in callee_ids:
                return True
    return False


def eval_test_references(args, graph):
    """An inbound edge whose source symbol's file_path matches
    TEST_PATH_PATTERN. Any relation type counts - the heuristic is about
    where the reference comes from, not what kind of reference it is."""
    ids = {s["id"] for s in _resolve_symbols(graph, args.get("symbol", ""))}
    if not ids:
        return False
    for edge in all_edges(graph):
        if edge.get("to_id") not in ids:
            continue
        source = graph["by_id"].get(edge.get("from_id"))
        if source and TEST_PATH_PATTERN.search(source.get("file_path") or ""):
            return True
    return False


def eval_literal_in_body(args, graph):
    """Regex search for `value` within the symbol's source range. Falls back
    to the whole file when the snapshot carries no start_line/end_line -
    evidence notes the window was widened so a pass there is legible as
    weaker than a range-scoped one."""
    value = args.get("value", "")
    if not value:
        return None
    candidates = _resolve_symbols(graph, args.get("symbol", ""))
    if not candidates:
        return False
    repo = graph["repo"]
    for rec in candidates:
        path = rec.get("file_path")
        if not path:
            continue
        try:
            lines = open(os.path.join(repo, path), encoding="utf-8", errors="replace").readlines()
        except OSError:
            continue
        start, end = rec.get("start_line"), rec.get("end_line")
        snippet = "".join(lines[start - 1 : end]) if start and end else "".join(lines)
        if re.search(re.escape(value), snippet):
            return True
    return False


EVALUATORS = {
    "symbol_exists": eval_symbol_exists,
    "has_inbound_edge": eval_has_inbound_edge,
    "calls": eval_calls,
    "test_references": eval_test_references,
    "literal_in_body": eval_literal_in_body,
}


def describe_evidence(atype, args, result):
    """What was checked and what was found, for the evidence column."""
    if atype == "symbol_exists":
        return f"regex search for /{args.get('pattern')}/ in symbol names: {'match' if result else 'no match'}"
    if atype == "has_inbound_edge":
        return f"inbound relations to '{args.get('symbol')}': {'found' if result else 'none found'}"
    if atype == "calls":
        return f"CALLS/ASYNC_CALLS from '{args.get('caller')}' to '{args.get('callee')}': {'found' if result else 'none found'}"
    if atype == "test_references":
        return f"inbound edge from a test-path file to '{args.get('symbol')}': {'found' if result else 'none found'}"
    if atype == "literal_in_body":
        return f"regex search for {args.get('value')!r} in '{args.get('symbol')}' source: {'found' if result else 'not found'}"
    return "no evidence"


