#!/usr/bin/env python3
"""drift: verify that requirements stated in an AI coding session landed in the code.

Invariant: the model reads English (one call, in extract_requirements), the
graph checks code. Everything after extraction is subprocess output, dict
lookups, and regex - no model call in the verification path.
"""
import argparse
import json
import os
import re
import subprocess
import sys

import requests

ASSERTION_TYPES = {
    "symbol_exists",
    "has_inbound_edge",
    "calls",
    "test_references",
    "literal_in_body",
}
STRUCTURAL_RELATIONS = {"DEFINES", "CONTAINS", "FILE_CHANGES_WITH"}

ANTHROPIC_API_URL = "https://api.anthropic.com/v1/messages"
ANTHROPIC_VERSION = "2023-06-01"
EXTRACTION_MODEL = "claude-haiku-4-5"

OLLAMA_CHAT_URL = "http://localhost:11434/api/chat"
OLLAMA_MODEL = os.environ.get("OLLAMA_MODEL", "llama3.1")

EXTRACTION_SYSTEM = """You turn a coding session's user requests into a checklist \
of verifiable requirements. You never see the code that was written and you never \
judge whether anything landed - a separate deterministic system does that.

For each distinct requirement you find, choose exactly one assertion type from this \
closed list and fill its arguments:

  symbol_exists(pattern)        a function/class/symbol matching a regex must exist
  has_inbound_edge(symbol)      something else in the code must reference this symbol
  calls(caller, callee)         `caller` must call `callee`
  test_references(symbol)       a test must reference this symbol
  literal_in_body(symbol, value) the literal `value` must appear in symbol's source

If a requirement does not cleanly fit one of these five, use {"type": "unverifiable"} \
instead of forcing a bad fit. Do not invent a sixth type."""

# Passed as the Ollama `format` / Anthropic `output_config.format` so the
# decoder is constrained to this shape at decode time - no fence stripping,
# no post-hoc repair, on either backend.
REQUIREMENTS_SCHEMA = {
    "type": "array",
    "items": {
        "type": "object",
        "properties": {
            "requirement": {"type": "string"},
            "assertion": {
                "type": "object",
                "properties": {
                    "type": {
                        "type": "string",
                        "enum": sorted(ASSERTION_TYPES | {"unverifiable"}),
                    },
                    "args": {
                        "type": "object",
                        "properties": {
                            "pattern": {"type": "string"},
                            "symbol": {"type": "string"},
                            "caller": {"type": "string"},
                            "callee": {"type": "string"},
                            "value": {"type": "string"},
                        },
                        "additionalProperties": False,
                    },
                },
                "required": ["type", "args"],
                "additionalProperties": False,
            },
        },
        "required": ["requirement", "assertion"],
        "additionalProperties": False,
    },
}


def extract_requirements(user_prompts, backend="local"):
    """The one LLM call in this program. `user_prompts` is user-role prompt
    text only - never assistant text, never tool_use payloads - so this
    extracts what was asked for, not a summary of what the agent did.
    Swappable backend, same return shape either way; nothing downstream
    knows or cares which ran."""
    if backend == "local":
        items = _extract_local(user_prompts)
    elif backend == "api":
        items = _extract_api(user_prompts)
    else:
        raise SystemExit(f"unknown backend: {backend}")
    return _close_assertion_enum(items)


def _extract_local(user_prompts):
    """Ollama, local and offline."""
    response = requests.post(
        OLLAMA_CHAT_URL,
        json={
            "model": OLLAMA_MODEL,
            "messages": [
                {"role": "system", "content": EXTRACTION_SYSTEM},
                {"role": "user", "content": user_prompts},
            ],
            "format": REQUIREMENTS_SCHEMA,
            "stream": False,
        },
        timeout=300,
    )
    response.raise_for_status()
    content = response.json()["message"]["content"]
    try:
        return json.loads(content)
    except json.JSONDecodeError as exc:
        raise SystemExit(f"ollama returned malformed JSON despite a constraining schema: {exc}\n{content}")


def _extract_api(user_prompts):
    """Anthropic Messages API, hosted fallback. The API's structured-output
    schema needs an object root, so the array is wrapped/unwrapped around
    the call; the returned shape is unaffected."""
    api_key = os.environ.get("ANTHROPIC_API_KEY")
    if not api_key:
        raise SystemExit("ANTHROPIC_API_KEY is not set")
    wrapped_schema = {
        "type": "object",
        "properties": {"requirements": REQUIREMENTS_SCHEMA},
        "required": ["requirements"],
        "additionalProperties": False,
    }
    response = requests.post(
        ANTHROPIC_API_URL,
        headers={
            "content-type": "application/json",
            "x-api-key": api_key,
            "anthropic-version": ANTHROPIC_VERSION,
        },
        json={
            "model": EXTRACTION_MODEL,
            "max_tokens": 8192,
            "system": EXTRACTION_SYSTEM,
            "messages": [{"role": "user", "content": user_prompts}],
            "output_config": {"format": {"type": "json_schema", "schema": wrapped_schema}},
        },
        timeout=180,
    )
    response.raise_for_status()
    text = next(b.get("text", "") for b in response.json()["content"] if b.get("type") == "text")
    try:
        return json.loads(text)["requirements"]
    except json.JSONDecodeError as exc:
        raise SystemExit(f"anthropic returned malformed JSON despite a constraining schema: {exc}\n{text}")


def _close_assertion_enum(items):
    """Reject any assertion type outside the closed enum, however it got
    there - a backend cannot author a new one."""
    requirements = []
    for item in items:
        assertion = item.get("assertion", {})
        if assertion.get("type") not in ASSERTION_TYPES:
            assertion = {"type": "unverifiable"}
        requirements.append({"requirement": item.get("requirement", ""), "assertion": assertion})
    return requirements


def run_entire(args, repo):
    proc = subprocess.run(["entire", *args], cwd=repo, capture_output=True, text=True, check=True)
    return proc.stdout


# ---------------------------------------------------------------------------
# Step 1: transcript parsing
# ---------------------------------------------------------------------------

def parse_transcript(raw):
    """Group transcript JSONL lines into turns by message boundary, not by
    line: the transcript is one line per content block, so a streamed
    assistant message (thinking + tool_use) is multiple lines sharing one
    API message id that must collapse into a single turn. A line with no
    message id (real user prompts, and synthetic tool-result messages) is
    already a whole message and is its own turn.

    Each turn: {index, role, kind, text, tool_uses: [{name, input}]}. `kind`
    is "prompt" (real human message), "tool_result" (synthetic), or
    "assistant". Only the turn index is ever surfaced downstream - no
    block-level position leaks out.
    """
    turns = []
    current_key = object()
    current = None
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        role = record.get("role") or record.get("message", {}).get("role")
        if role not in ("user", "assistant"):
            continue
        message = record.get("message", record)
        content = message.get("content")
        msg_id = message.get("id")
        key = (role, msg_id) if msg_id else (role, id(record))

        if key != current_key:
            current = {
                "index": len(turns),
                "role": role,
                "kind": "assistant" if role == "assistant" else "prompt",
                "text_parts": [],
                "tool_uses": [],
            }
            turns.append(current)
            current_key = key

        if isinstance(content, str):
            current["text_parts"].append(content)
        elif isinstance(content, list):
            for block in content:
                if not isinstance(block, dict):
                    continue
                btype = block.get("type")
                if btype == "text":
                    current["text_parts"].append(block.get("text", ""))
                elif btype == "tool_use":
                    current["tool_uses"].append({"name": block.get("name", ""), "input": block.get("input", {})})
                elif btype == "tool_result":
                    current["kind"] = "tool_result"

    for turn in turns:
        turn["text"] = "\n".join(turn.pop("text_parts"))
    return turns


# ---------------------------------------------------------------------------
# Step 3: graph index
# ---------------------------------------------------------------------------

def build_graph_index(raw):
    """Two indexes from `entire graph snapshot` ndjson: symbols by name,
    edges by source id. `by_id` is kept alongside purely to resolve relation
    endpoints back to symbol records - an implementation detail of the same
    index, not a third independent one."""
    symbols_by_name = {}
    symbols_by_id = {}
    edges_by_source = {}
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        rtype = record.get("record_type")
        if rtype == "symbol":
            symbols_by_name.setdefault(record.get("name"), []).append(record)
            symbols_by_id[record.get("id")] = record
        elif rtype == "relation":
            edges_by_source.setdefault(record.get("from_id"), []).append(record)
    return {"by_name": symbols_by_name, "by_id": symbols_by_id, "edges_by_source": edges_by_source}


def find_symbols(graph, pattern):
    """Symbol records whose name or qualified_name matches a regex SEARCH
    (substring position, not full-string equality) - "run" matches
    "run_entire"."""
    try:
        rx = re.compile(pattern)
    except re.error:
        rx = re.compile(re.escape(pattern))
    matches = []
    for name, records in graph["by_name"].items():
        if rx.search(name or ""):
            matches.extend(records)
            continue
        matches.extend(rec for rec in records if rx.search(rec.get("qualified_name") or ""))
    return matches


def all_edges(graph):
    for edges in graph["edges_by_source"].values():
        yield from edges


def _resolve_symbols(graph, name):
    """Exact name match first; only fall back to find_symbols's regex/
    substring search if nothing matches exactly, so an unambiguous name
    doesn't get diluted by unrelated substring hits."""
    exact = graph["by_name"].get(name)
    return exact if exact else (find_symbols(graph, name) if name else [])


# ---------------------------------------------------------------------------
# Step 4: assertion evaluators
# ---------------------------------------------------------------------------

CALL_RELATION_TYPES = {"CALLS", "ASYNC_CALLS"}  # the snapshot's relation_set
# does distinguish calls from other relation types - not approximated.

# Heuristic for "looks like a test": a test(s)/__tests__ path segment, or a
# filename ending in _test.<ext>. Stated here since there's no other
# definition of "test" to go on.
TEST_PATH_PATTERN = re.compile(r"(^|/)(tests?|__tests__)(/|$)|_test\.[^/.]+$", re.IGNORECASE)


def eval_symbol_exists(args, graph):
    """Never None - existence is always answerable."""
    return bool(find_symbols(graph, args.get("pattern", "")))


def eval_has_inbound_edge(args, graph):
    """Any relation, of any type, from any source, landing on this symbol.
    False (not None) when the symbol doesn't exist: nonexistence definitively
    means no inbound edge."""
    ids = {s["id"] for s in _resolve_symbols(graph, args.get("symbol", ""))}
    return bool(ids) and any(edge.get("to_id") in ids for edge in all_edges(graph))


def eval_calls(args, graph):
    """A CALLS/ASYNC_CALLS relation from a caller-matching id to a
    callee-matching id."""
    caller_ids = [s["id"] for s in _resolve_symbols(graph, args.get("caller", ""))]
    callee_ids = {s["id"] for s in _resolve_symbols(graph, args.get("callee", ""))}
    if not caller_ids or not callee_ids:
        return False
    return any(
        edge.get("type") in CALL_RELATION_TYPES and edge.get("to_id") in callee_ids
        for cid in caller_ids
        for edge in graph["edges_by_source"].get(cid, [])
    )


def eval_test_references(args, graph):
    """An inbound edge whose source symbol's file_path matches
    TEST_PATH_PATTERN. Any relation type counts - the heuristic is about
    where the reference comes from, not what kind it is."""
    ids = {s["id"] for s in _resolve_symbols(graph, args.get("symbol", ""))}
    if not ids:
        return False
    for edge in all_edges(graph):
        if edge.get("to_id") in ids:
            source = graph["by_id"].get(edge.get("from_id"))
            if source and TEST_PATH_PATTERN.search(source.get("file_path") or ""):
                return True
    return False


def eval_literal_in_body(args, graph):
    """Regex search for `value` within the symbol's source range. Falls back
    to the whole file when the snapshot has no start_line/end_line - the
    evidence string names this as a widened window."""
    value = args.get("value", "")
    if not value:
        return None
    candidates = _resolve_symbols(graph, args.get("symbol", ""))
    if not candidates:
        return False
    repo = graph["repo"]
    for rec in candidates:
        path = rec.get("file_path")
        if not path:
            continue
        try:
            lines = open(os.path.join(repo, path), encoding="utf-8", errors="replace").readlines()
        except OSError:
            continue
        start, end = rec.get("start_line"), rec.get("end_line")
        snippet = "".join(lines[start - 1 : end]) if start and end else "".join(lines)
        if re.search(re.escape(value), snippet):
            return True
    return False


EVALUATORS = {
    "symbol_exists": eval_symbol_exists,
    "has_inbound_edge": eval_has_inbound_edge,
    "calls": eval_calls,
    "test_references": eval_test_references,
    "literal_in_body": eval_literal_in_body,
}


def describe_evidence(atype, args, result):
    """What was checked and what was found, for the evidence column."""
    found = "found" if result else "not found"
    if atype == "symbol_exists":
        return f"regex search for /{args.get('pattern')}/ in symbol names: {'match' if result else 'no match'}"
    if atype == "has_inbound_edge":
        return f"inbound relations to '{args.get('symbol')}': {found}"
    if atype == "calls":
        return f"CALLS/ASYNC_CALLS from '{args.get('caller')}' to '{args.get('callee')}': {found}"
    if atype == "test_references":
        return f"inbound edge from a test-path file to '{args.get('symbol')}': {found}"
    if atype == "literal_in_body":
        return f"regex search for {args.get('value')!r} in '{args.get('symbol')}' source: {found}"
    return "no evidence"


# ---------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo", required=True)
    parser.add_argument("--checkpoint", required=True)
    parser.add_argument("--backend", choices=["local", "api"], default="local")
    args = parser.parse_args()

    transcript_raw = run_entire(["checkpoint", "explain", args.checkpoint, "--transcript"], args.repo)
    turns = parse_transcript(transcript_raw)

    graph_raw = run_entire(["graph", "snapshot", "--repo", ".", "--format", "ndjson"], args.repo)
    graph = build_graph_index(graph_raw)
    graph["repo"] = args.repo

    print(f"parsed {len(turns)} turns")
    print(f"parsed {len(graph['by_id'])} symbols")

    prompt_text = "\n\n".join(t["text"] for t in turns if t["kind"] == "prompt")
    requirements = extract_requirements(prompt_text, backend=args.backend)

    rows = []
    deferred = 0
    for req in requirements:
        assertion = req["assertion"]
        atype = assertion["type"]
        evaluator = EVALUATORS.get(atype)
        result = evaluator(assertion.get("args", {}), graph) if evaluator else None
        if result is None:
            deferred += 1
            continue
        verdict = "landed" if result else "absent"
        evidence = describe_evidence(atype, assertion.get("args", {}), result)
        rows.append((req["requirement"], verdict, evidence))

    label_width = min(60, max((len(r[0]) for r in rows), default=10))
    print(f"\n{'requirement':<{label_width}}  {'verdict':<8}  evidence")
    for requirement, verdict, evidence in rows:
        label = requirement if len(requirement) <= label_width else requirement[: label_width - 1] + "…"
        print(f"{label:<{label_width}}  {verdict:<8}  {evidence}")
    print(f"\n({deferred} requirement(s) deferred to a later stage: unverifiable type or no answer)")

    if any(verdict == "absent" for _, verdict, _ in rows):
        sys.exit(1)


if __name__ == "__main__":
    main()

