import time
from typing import Callable, TypeVar

T = TypeVar("T")

MAX_ATTEMPTS = 5


def call_with_retry(func: Callable[[], T], max_attempts: int = MAX_ATTEMPTS) -> T:
    """Call `func`, retrying with exponential backoff up to `max_attempts` times."""
    last_exc: Exception = RuntimeError("max_attempts must be at least 1")
    for attempt in range(max_attempts):
        try:
            return func()
        except Exception as exc:
            last_exc = exc
            time.sleep(2 ** attempt)
    raise last_exc

import requests

from .retry import call_with_retry


class HttpClient:
    """Minimal HTTP client with retrying GET requests."""

    def __init__(self, timeout: float = 5.0):
        self.timeout = timeout

    def get(self, url: str) -> requests.Response:
        return call_with_retry(lambda: requests.get(url, timeout=self.timeout))

from httpclient.retry import call_with_retry


def test_call_with_retry_succeeds_after_failures():
    calls = {"count": 0}

    def flaky():
        calls["count"] += 1
        if calls["count"] < 3:
            raise ValueError("boom")
        return "ok"

    assert call_with_retry(flaky) == "ok"
    assert calls["count"] == 3

