def find_dropped_turn(turns, atype, args):
    """For an `absent` verdict: scan Write/Edit tool_use payloads BACKWARDS
    (most recent turn first) for the requirement's symbol/literal. A hit that
    is confirmed absent from the final graph is `dropped`, attributed to the
    last turn it appeared in - textual attribution, per the open risk noted
    in the design: it can misattribute if an unrelated later turn happens to
    reuse the same string. Returns None (stays `absent`) if it never
    appeared in a write or edit at all."""
    patterns = []
    for needle in _DROP_NEEDLES.get(atype, lambda a: [])(args):
        if not needle:
            continue
        try:
            patterns.append(re.compile(needle))
        except re.error:
            patterns.append(re.compile(re.escape(needle)))
    if not patterns:
        return None
    for turn in reversed(turns):
        for tool_use in turn["tool_uses"]:
            if tool_use["name"] not in ("Write", "Edit"):
                continue
            inp = tool_use["input"]
            text = inp.get("content", "") + inp.get("old_string", "") + inp.get("new_string", "")
            if any(p.search(text) for p in patterns):
                return turn["index"]
    return None

